def src(title,url):return dict(title=title,url=url,checked=CHECKED)
def ref(label,url):return dict(label=label,url=url)
def E(ident,title,iso,url,start='',end='',**fields):
    country=T('Непал','Nepal')if iso=='NPL'else T('Мальдивские Острова','Maldivas')
    e=event(ident,title,country,url,start,end,**fields)
    e.update(country=country,region=T('Азия','Asia'),iso=[iso],checked=CHECKED)
    for k,v in dict(entry=GATE,action=GATE,language=LANG,language_certainty=LANG,cost=UNKNOWN,note=AWARD,reward=AWARD,level=T('B — национальная / региональная программа','B — programa nacional / regional')).items():
        if k not in fields:e[k]=v
    return e
def P(i,slug,name,iso,age,themes,lo=0,hi=99,formats=('day',)):
    p=base('CP'+str(i),slug,name,iso,T('Непал','Nepal')if iso=='NPL'else T('Мальдивские Острова','Maldivas'),'Kathmandu'if iso=='NPL'else'Maldives',themes)
    p.update(age=age,formats=list(formats),language=LANG,confirmed_instruction_languages=[],language_evidence_role='unconfirmed',checked=CHECKED,family_fit=fit(lo,hi),questions=[GATE],editorial_reason=AWARD,shortlist=[])
    p['timing'].update(status='next_unannounced',label=UNKNOWN,sessions=[],session_details=[],variant_keyed=True)
    p['price'].update(amount=None,currency='NPR'if iso=='NPL'else'USD',year=None,unit='programme',label=UNKNOWN,extras=TRIP,deposit=UNKNOWN)
    if 'family'in formats:p['accommodation']=RESORT
    return p

